/**
 * Live/realtime audio bridge tests — the covenant between the curated
 * catalog (`audio/catalog.ts`) and the auto-synced id roster
 * (`audio/openai-live.generated.ts`, regenerated by the catalog-sync
 * `audio:openai-live` generator from OpenAI's pinned /v1/models snapshot).
 *
 * What must hold, in one line each:
 *   - the synced roster is provider metadata (modality audio, kind live);
 *   - the curated overlay claims ids the provider actually serves;
 *   - the curation flag (`needsCuration` / `openaiLiveIdsNeedingCuration`)
 *     is a faithful function of the curated catalog — no more, no less.
 */
import { describe, it, expect, vi } from "vitest"

// The synced roster is replaced by a fixture so these tests assert the
// roster/overlay contract, not which ids OpenAI serves this week. The one
// check that IS about live drift lives in audio-live.drift.test.ts.
vi.mock("../audio/openai-live.generated.js", () => {
  const live = (id: string, needsCuration: boolean) => ({
    providerId: id, modality: "audio", kind: "live", needsCuration, ownedBy: "system", createdAt: "2026-01-01",
  })
  return {
    OPENAI_LIVE_MODELS: {
      "gpt-live-1": live("gpt-live-1", false),
      "gpt-live-1.1": live("gpt-live-1.1", false),
      "gpt-realtime-fixture-uncurated": live("gpt-realtime-fixture-uncurated", true),
    },
  }
})

const {
  OPENAI_LIVE_MODELS,
  OPENAI_LIVE_MODEL_IDS,
  CURATED_OPENAI_AUDIO_PROVIDER_IDS,
  isCuratedOpenAIAudioModel,
  openaiLiveIdsNeedingCuration,
} = await import("../audio/live.js")
const { AUDIO_MODEL_CATALOG } = await import("../audio/catalog.js")

describe("synced OpenAI live roster (openai-live.generated.ts)", () => {
  it("exposes the roster ids and excludes date-pinned variants", () => {
    expect(OPENAI_LIVE_MODEL_IDS).toEqual(Object.keys(OPENAI_LIVE_MODELS))
    expect(OPENAI_LIVE_MODEL_IDS).not.toContain("gpt-realtime-2025-08-28")
  })

  it("every entry is an audio live-engine keyed by its provider id", () => {
    for (const [id, entry] of Object.entries(OPENAI_LIVE_MODELS)) {
      expect(entry.providerId).toBe(id)
      expect(entry.modality).toBe("audio")
      expect(entry.kind).toBe("live")
      // Optional provenance fields are strings when present.
      for (const field of ["createdAt", "shutdownDate", "ownedBy"] as const) {
        if (entry[field] !== undefined) {
          expect(typeof entry[field]).toBe("string")
        }
      }
    }
  })
})

describe("curated overlay ↔ synced roster covenant", () => {
  it("needsCuration is exactly the curated-overlay membership function", () => {
    for (const [id, entry] of Object.entries(OPENAI_LIVE_MODELS)) {
      expect(entry.needsCuration).toBe(!isCuratedOpenAIAudioModel(id))
    }
    // And the debt list reports precisely the flagged ids.
    expect([...openaiLiveIdsNeedingCuration()]).toEqual(
      Object.entries(OPENAI_LIVE_MODELS)
        .filter(([, e]) => e.needsCuration)
        .map(([id]) => id),
    )
  })

  it("every GPT-Live entry is curated (base + 1.1 bill as live engines)", () => {
    // The mission-critical curated pair: a GPT-Live id reaching this catalog
    // as a synced-but-uncurated row would be call-engine billing debt.
    expect(isCuratedOpenAIAudioModel("gpt-live-1")).toBe(true)
    expect(isCuratedOpenAIAudioModel("gpt-live-1.1")).toBe(true)
    expect(AUDIO_MODEL_CATALOG["openai/gpt-live-1"]!.providerId).toBe("gpt-live-1")
    expect(AUDIO_MODEL_CATALOG["openai/gpt-live-1.1"]!.providerId).toBe("gpt-live-1.1")
    expect(OPENAI_LIVE_MODELS["gpt-live-1"]!.needsCuration).toBe(false)
    expect(OPENAI_LIVE_MODELS["gpt-live-1.1"]!.needsCuration).toBe(false)
  })

  it("the curated provider ids are the openai half of AUDIO_MODEL_CATALOG", () => {
    expect(CURATED_OPENAI_AUDIO_PROVIDER_IDS).toEqual(
      Object.values(AUDIO_MODEL_CATALOG)
        .filter(m => m.provider === "openai")
        .map(m => m.providerId),
    )
  })
})
